-- Synthetic Cindy database: schema plus one slice of sessions, messages and daily aggregates.
CREATE TABLE sessions (id TEXT PRIMARY KEY, title TEXT, working_dir TEXT, project_dir TEXT, model TEXT, provider_id TEXT, agent_kind TEXT DEFAULT 'codex', parent_session_id TEXT, total_token_usage INTEGER DEFAULT 0, total_cost_usd REAL DEFAULT 0, total_cost_amount REAL DEFAULT 0, total_cost_currency TEXT, total_cost_is_approximate INTEGER DEFAULT 0, created_at INTEGER, updated_at INTEGER, last_activity_at INTEGER, status TEXT DEFAULT 'active')
CREATE TABLE messages (id TEXT PRIMARY KEY, client_id TEXT, session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT, tool_use_id TEXT, created_at INTEGER NOT NULL, agent_meta TEXT, rewind_at INTEGER, agent_kind TEXT)
CREATE TABLE daily_model_usage (day TEXT NOT NULL, agent_kind TEXT NOT NULL DEFAULT 'codex', model TEXT NOT NULL, cost_usd REAL NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0, cost_amount REAL, cost_currency TEXT, cost_is_approximate INTEGER NOT NULL DEFAULT 0, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cache_read_tokens INTEGER NOT NULL DEFAULT 0, cache_create_tokens INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, agent_kind, model))
